INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_1', 'subj_wassce_sculpture', 'Cultural and historical sculpture', 'sculpture-b004-1', 'Interpret sculpture through credible cultural context, including animism in West African traditions and the representation of athletes in Greek sculpture.', 1);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_1', 'spec_wassce_sculpture_brilla_b004', 'SC-1', 'Cultural and historical sculpture', 'Interpret sculpture through credible cultural context, including animism in West African traditions and the representation of athletes in Greek sculpture.', '["AO1","AO2","AO3"]', 1);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_2', 'subj_wassce_sculpture', 'Materials, terminology and studio safety', 'sculpture-b004-2', 'Use precise sculpture terminology, distinguish material properties and control dust, impact, heat and chemical hazards.', 2);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_2', 'spec_wassce_sculpture_brilla_b004', 'SC-2', 'Materials, terminology and studio safety', 'Use precise sculpture terminology, distinguish material properties and control dust, impact, heat and chemical hazards.', '["AO1","AO2","AO3"]', 2);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_3', 'subj_wassce_sculpture', 'Modelling, coiling and terracotta preparation', 'sculpture-b004-3', 'Prepare terracotta clay systematically and build sound modelled or coiled forms through compatible joining and controlled drying.', 3);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_3', 'spec_wassce_sculpture_brilla_b004', 'SC-3', 'Modelling, coiling and terracotta preparation', 'Prepare terracotta clay systematically and build sound modelled or coiled forms through compatible joining and controlled drying.', '["AO1","AO2","AO3"]', 3);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_4', 'subj_wassce_sculpture', 'Carving and relief processes', 'sculpture-b004-4', 'Plan carving and relief by reading grain, establishing depth, preserving allowances and refining form safely.', 4);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_4', 'spec_wassce_sculpture_brilla_b004', 'SC-4', 'Carving and relief processes', 'Plan carving and relief by reading grain, establishing depth, preserving allowances and refining form safely.', '["AO1","AO2","AO3"]', 4);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'Indirect methods, moulding and casting', 'sculpture-b004-5', 'Distinguish direct and indirect production, then plan mould divisions, releases, gates, vents and controlled casting mixes.', 5);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_5', 'spec_wassce_sculpture_brilla_b004', 'SC-5', 'Indirect methods, moulding and casting', 'Distinguish direct and indirect production, then plan mould divisions, releases, gates, vents and controlled casting mixes.', '["AO1","AO2","AO3"]', 5);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_6', 'subj_wassce_sculpture', 'Construction and assemblage', 'sculpture-b004-6', 'Join compatible components, stabilise structures and integrate fabricated or found elements into durable sculpture.', 6);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_6', 'spec_wassce_sculpture_brilla_b004', 'SC-6', 'Construction and assemblage', 'Join compatible components, stabilise structures and integrate fabricated or found elements into durable sculpture.', '["AO1","AO2","AO3"]', 6);
INSERT OR IGNORE INTO topics (id, subject_id, name, slug, description, display_order) VALUES ('topic_was_sculpture_b004_7', 'subj_wassce_sculpture', 'Design, figure, finishing and presentation', 'sculpture-b004-7', 'Control mass, negative space, gesture, anatomy, surface, lighting and display to communicate sculptural intent.', 7);
INSERT OR IGNORE INTO syllabus_topics (id, specification_id, topic_code, title, description, assessment_objectives, display_order) VALUES ('st_was_sculpture_b004_7', 'spec_wassce_sculpture_brilla_b004', 'SC-7', 'Design, figure, finishing and presentation', 'Control mass, negative space, gesture, anatomy, surface, lighting and display to communicate sculptural intent.', '["AO1","AO2","AO3"]', 7);
